import{_ as e,w as n,s as a,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"戴着面具的復仇者 —— 揭秘：激進黑客組織“匿名者” | LCTT x X-CMD","titleTemplate":false,"description":"戴着面具的復仇者 —— 揭秘：激進黑客組織“匿名者” | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴着面具的復仇者 —— 揭秘：激進黑客組織“匿名者” | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴着面具的復仇者 —— 揭秘：激進黑客組織“匿名者” | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140904 The Masked Avengers","title":"戴着面具的復仇者 —— 揭秘：激進黑客組織“匿名者”","tag":"201409","desc":""},"relativePath":"201409/20140904 The Masked Avengers.md","filePath":"[post].md"}'),p={name:"201409/20140904 The Masked Avengers.md"};function r(l,o,s,c,y,i){return n(),a("div",null,[...o[0]||(o[0]=[t('<h1 id="戴着面具的復仇者-——-揭秘-激進黑客組織-匿名者" tabindex="-1">戴着面具的復仇者 —— 揭秘：激進黑客組織“匿名者” <a class="header-anchor" href="#戴着面具的復仇者-——-揭秘-激進黑客組織-匿名者" aria-label="Permalink to “戴着面具的復仇者 —— 揭秘：激進黑客組織“匿名者””">​</a></h1><blockquote><em>從“<a href="https://zh.wikipedia.org/wiki/%E8%8C%89%E8%8E%89%E8%8A%B1%E9%9D%A9%E5%91%BD">突尼斯政變</a>”到“<a href="https://zh.wikipedia.org/wiki/%E9%82%81%E5%85%8B%E7%88%BE%C2%B7%E5%B8%83%E6%9C%97%E6%A7%8D%E6%93%8A%E6%A1%88">弗格森槍擊事件</a>”，“匿名者”組織是如何煽動起網絡示威活動的。</em></blockquote><img src="https://www.newyorker.com/wp-content/uploads/2014/09/140908_r25419-690.jpg"><blockquote><em>通過入會聲明，任何人都能輕易加入“匿名者”組織。某人類學家稱，組織成員會“根據影響程度對重大事件保持着不同關注，特別是那些能挑起強烈爭端的事件”。</em></blockquote><p><small>紙雕作品：Jeff Nishinaka / 攝影：Scott Dunbar</small></p><h2>1</h2><p>上世紀七十年代中期，當 Christopher Doyon 還是一個生活在緬因州鄉村的孩童時，就終日泡在 CB radio 上與各種陌生人聊天。他的暱稱是“Big red”(大紅)，因為他有一頭紅色的頭髮。Christopher Doyon 把發射機掛在了卧室的牆壁上，並且説服了父親在自家屋頂安裝了兩根天線。CB radio 主要用於卡車司機間的聯絡，但 Doyon 和一些人卻將之用於不久後出現在 Internet 上的虛擬社交——自定義暱稱、成員間才懂的笑話，以及施行變革的強烈願望。</p><p>Doyon 很小的時候母親就去世了，兄妹二人由父親撫養長大，他倆都説受到過父親的虐待。由此 Doyon 在 CB radio 社區中找到了慰藉和目標感。他和他的朋友們輪流監聽當地緊急事件頻道。其中一個朋友的父親買了一個氣泡燈並安裝在了他的車頂上；每當這個孩子收聽到來自孤立無援的乘車人的求助後，都會開車載着所有人到求助者所在的公路旁。除了撥打 911 外他們基本沒有什麼可做的，但這足以讓他們感覺自己成為了英雄。</p><p>短小精悍的 Doyon 有着一口濃厚的新英格蘭口音，並且非常喜歡《星際迷航》和阿西莫夫的小説。當他在《大眾機械》上看到一則“組裝你的專屬個人計算機”構件廣告時，就央求祖父給他買一套，接下來 Doyon 花了數月的時間把計算機組裝起來並連接到 Internet 上去。與鮮為人知的 CB 電波相比，在線聊天室確實不可同日而語。“我只需要點一下按鈕，再選中某個傢伙的名字，然後我就可以和他聊天了，” Doyon 在最近回憶時説道，“這真的很驚人。”</p><p>十四歲那年，Doyon 離家出走，兩年後他搬到了馬薩諸塞州的劍橋，那裏是一個新出現的計算機反主流文化的中心。同一時間，早在 34 年前就已由麻省理工學院的鐵路狂熱愛好者們創立的鐵路模型技術俱樂部，已經演變成了“黑客”——也是推廣該詞的第一個組織。Richard Stallman，在那時還是一名任職於麻省理工學院人工智能實驗室的計算機科學家，指出早期黑客們比起引發技術戰爭更樂於討論“哥德爾、艾舍爾、巴赫”之類的話題。“我們沒有任何約束”，Stallman 説，“這不是一項運動，而是一種可以讓人們相互留下深刻印象的行為。”其中有些“行為”很有趣（製作電子遊戲）；有些非常實用（提高計算機處理速度）；還有些則屬於發生在真實世界裏的惡作劇（在校園內放置模擬街道標識）。Michael Patton，在七十年代裏管理着鐵路模型技術俱樂部的人，談起初代黑客間不成文的規定，説第一條就是“不要搞破壞”。</p><p>在劍橋，Doyon 以打零工和乞討為生，他寧願為了自由而睡在公園的長椅上，也不願被單調的固定工作所束縛。1985 年，他和其他六個活躍分子共同組建了一支電子“義勇軍”。模仿“動物解放陣線”，他們稱呼自己為“人民解放陣線”（Peoples Liberation Front，PLF）。所有人都使用化名：如組織的創建者，聲稱自己是老兵的一位高大中年男子，自稱“Commander Adama”；Doyon 則選擇了“Commander X”這個稱呼。受 “Merry Pranksters” 啓示，他們在 Grateful Dead 的演唱會上出售 LSD（lysergic acid diethylamide，麥角酸酰二乙胺，一種迷幻藥），並用收入的一部分購置了一輛二手校車，以及擴音器、相機，還有電源充電器。同時在劍橋租了一間地下公寓，Doyon 偶爾會在那裏歇息。</p><p>Doyon 深深地沉溺於計算機中，雖然他並不是一位專業的程序員。在過去一年的幾次談話中，他告訴我他將自己視為激進主義分子，繼承了 Abbie Hoffman 和 Eldridge Cleaver 的激進傳統；技術不過是他抗議的工具。八十年代，哈佛大學和麻省理工學院的學生們舉行集會，強烈抗議他們的學校從南非撤資。為了幫助抗議者通過安全渠道進行交流，PLF 製作了無線電套裝：移動調頻發射器、伸縮式天線，還有麥克風，所有部件都內置於背包內。Willard Johnson，麻省理工學院的一位激進分子和政治學家，表示黑客們出席集會並不意味着一次變革。“我們的大部分工作仍然是通過擴音器來完成的，”他解釋道。</p><p>1992 年，在印第安納的一場 Grateful Dead 的演唱會上，Doyon 秘密地向一位癮君子出售了 300 粒藥。由此他被判決在印第安納州立監獄服役十二年，後來改為五年。服役期間，他對宗教和哲學產生了濃厚的興趣，並於鮑爾州立大學學習了相應課程。</p><p>1994 年，第一款商業 Web 瀏覽器 Netscape Navigator（網景領航員）正式發佈，同一年 Doyon 被捕入獄。當他出獄並再次回到劍橋後，PLF 依然活躍着，並且他們的工具有了實質性的飛躍。Doyon 回憶起他和入獄之前對比的變化，“非常巨大——好比是‘烽火狼煙’跟‘電報傳信’之間那麼大的差距。”黑客們入侵了一個印度的軍事網站，並修改其首頁文字為“拯救克什米爾”。在塞爾維亞，黑客們攻陷了一個阿爾巴尼亞網站。Stefan Wray，一位早期網絡激進主義分子，為一次紐約“反哥倫布日”集會上的黑客行徑辯護。“我們視之為電子形式的公眾抗議，”他告訴大家。</p><p>1999 年，美國唱片業協會因為版權侵犯問題起訴了 Napster，一款文件共享服務。最終，Napster 於 2001 年關閉。Doyon 與其他黑客使用分佈式拒絕服務（Distributed Denial of Service，DDoS，使大量數據湧入網站導致其響應速度減緩直至奔潰）的手段，攻擊了美國唱片業協會的網站，使之停運時間長達一星期之久。Doyon為自己的行為進行了辯解，並高度讚揚了其他的“黑客主義者”。“我們很快意識到保衞 Napster 的戰爭象徵着保衞 Internet 自由的戰爭，”他在後來寫道。</p><p>2008 年的一天，Doyon 和 “Commander Adama” 在劍橋的 PLE 地下公寓相遇。Adama 當着 Doyon 的麪點擊了癲癇基金會的一個鏈接，與意料中將要打開的論壇不同，出現的是一連串閃爍的彩光。有些癲癇病患者對閃光燈非常敏感——這完全是出於惡意，有人想要在無辜羣眾中誘發癲癇病。已經出現了至少一名受害者。</p><p>Doyon 憤怒了。他質問 Adama 什麼樣的人才會做出這樣的事來。</p><p>“你聽説過‘匿名者’組織嗎？” Adama 問。</p><h2>2</h2><p>2003 年，一位來自紐約的已經患病 15 年的失眠症患者 Christopher Poole，推出了 4chan 討論社區，在這裏用户們可以隨意發佈照片或者尖鋭評論。隨後其關注點迅速從動漫延伸到許多 Internet 的早期文化基因，如：LOLcats、Chocolate Rain、RickRolls。當用户沒有按照屏幕上的要求輸入暱稱時，將會得到系統默認的“匿名者”（Anonymous）稱呼。</p><img src="http://www.newyorker.com/wp-content/uploads/2014/09/140908_a18505-600.jpg"><p><small>“我得談談我的感受。”</small></p><p>Poole 希望匿名這一舉措可以延續社區的尖鋭性因素。“我們無意參與理智的涉外事件討論，”他在網站上寫道。4chan 社區裏最具價值的事之一便是尋求“挑起強烈的爭端”（lulz），這個詞源自縮寫 LOL。Lulz 經常是通過分享幼稚的笑話或圖片來實現的，其中大部分不是色情的就是下流的。其中最令人震驚的部分被貼在了網站的“/b/”版塊上，這裏的用户們稱呼自己為“/b/tards”。Doyon 知道 4chan 這個社區，但他認為它的用户是“一羣愚昧無知的頑童”。2004 年前後，/b/ 上的部分用户開始把“匿名者”視為一個獨立的實體。</p><p>這是一個全新的黑客團體。“這不是一個傳統意義上的組織，”一位領導計算機安全工作的研究員 Mikko Hypponen 告訴我——倒不如，視之為一個非傳統的亞文化羣體。Barrett Brown，德克薩斯州的一名記者,同時也是眾所周知的“匿名者”高層領導，把“匿名者”描述為“一連串前仆後繼的偉大友誼”。無需任何會費或者入會儀式。任何想要加入“匿名者”組織，成為一名匿名者（Anon）的人，都可以通過簡短的象徵性的宣誓加入。</p><p>儘管 4chan 的關注焦點是一些瑣碎的話題，但許多匿名者認為自己就是“正義的十字軍”。如果網上有不良跡象出現，他們就會發起具有針對性的治安維護行動。不止一次，他們以未成年少女的身份使戀童癖陷入圈套，然後把他們的個人信息交給警察局。其他匿名者則是政治的厭惡者，為了挑起爭端想方設法散佈混亂的信息。他們中的一些人在 /b/ 上發佈看着像是雷管炸彈的圖片；另一些則叫囂着要炸燬足球場並因此被聯邦調查局逮捕。2007 年，一家洛杉磯當地的新聞聯盟機構稱呼“匿名者”組織為“互聯網負能量製造機”。</p><p>2008 年 1 月，Gawker Media 上傳了一段關於湯姆克魯斯大力吹捧山達基優點的視頻。這段視頻是受版權保護的，山達基教會致信 Gawker，勒令其刪除這段視頻。“匿名者”組織認為教會企圖控制網絡信息。“是時候讓 /b/ 來幹票大的了，”有人在 4chan 上寫道。“我説的是‘入侵’或者‘攻陷’山達基官方網站。”一位匿名者使用 YouTube 放出一段“新聞稿”，其中包括暴雨雲視頻和經過計算機處理的語音。“我們要立刻把你們從 Internet 上趕出去，並且在現有規模上逐漸瓦解山達基教會，”那個聲音説，“你們無處可躲。”不到一個星期，這段 YouTube 視頻的點擊率就超過了兩百萬次。</p><p>“匿名者”組織已經不僅限於 4chan 社區。黑客們在專用的互聯網中繼聊天（Internet Relay Chat channels，IRC 聊天室）頻道內進行交流，協商策略。通過 DDoS 攻擊手段，他們使山達基的主網站間歇性崩潰了好幾天。匿名者們製造了“谷歌炸彈”，由此導致 “dangerous cult” 的搜索結果中的第一條結果就是山達基主網站。其餘的匿名者向山達基的歐洲總部寄送了數以百計的披薩，並用大量全黑的傳真單耗幹了洛杉磯教會總部的傳真機墨盒。山達基教會，據報道是一個擁有超過十億美元資產的組織，當然能經得起墨盒耗盡的考驗。但山達基教會的高層可不這麼認為，他們還收到了死亡恐嚇，由此他們不得不向 FBI 申請調查“匿名者”組織的成員。</p><p>2008 年 3 月 15 日，在從倫敦到悉尼的一百多個城市裏，數以千計匿名者們遊行示威山達基教會。為了切合“匿名”這個主題，組織者下令所有的抗議者都應該佩戴相同的面具。深思熟慮過蝙蝠俠後，他們選定了 2005 年上映的反烏托邦電影《 V 字仇殺隊》中 Guy Fawkes 的面具。“在每個大城市裏都能以很便宜的價格大量購買，”廣為人知的匿名者、遊行組織者之一 Gregg Housh 告訴我説道。漫畫式的面具上是一個的臉頰紅潤的男人，八字鬍，有着燦爛的笑容。</p><p>匿名者們並未“瓦解”山達基教會。並且湯姆克魯斯的那段視頻任然保留在網絡上。匿名者們證明了自己的頑強。組織選擇了一個相當浮誇的口號：“我們是軍團。絕不寬恕。永不遺忘。等待我們。”（We are Legion. We do not forgive. We do not forget. Expect us.）</p><h2>3</h2><p>2010 年，Doyon 搬到了加利福尼亞州的聖克魯斯，並加入了當地的“和平陣營”組織。利用從木材堆置場偷來的木頭，他在山上蓋起了一間簡陋的小屋，“借用”附近住宅的 WiFi，使用太陽能電池板發電，並通過販賣種植的大麻換取現金。</p><p>與此同時，“和平陣營”維權者們每天晚上開始在公共場所休息，以此抗議聖克魯斯政府此前頒佈的“流浪者管理法案”，他們認為這項法案嚴重侵犯了流浪者的生存權。Doyon 出席了“和平陣營”的會議，並在網上發起了抗議活動。他留着蓬亂的紅色山羊鬍，戴一頂米黃色軟呢帽，類似軍服的服裝。因此維權者們送給了他“罪惡制裁克里斯”的稱呼。</p><p>“和平陣營”的成員之一 Kelley Landaker 曾幾次和 Doyong 討論入侵事宜。Doyon 有時會吹噓自己的技術是多麼的厲害，但作為一名資深程序員的 Landaker 卻不為所動。“他説得很棒，但卻不是行動派，”Landaker 告訴我。不過在那種場合下，的確更需要一位富有激情的領導者，而不是埋頭苦幹的技術員。“他非常熱情並且坦率，”另一位成員 Robert Norse 如是對我説。“他創造出了大量的能夠吸引媒體眼球的話題。我從事這行已經二十年了，在這一點上他比我見過的任何人都要厲害。”</p><p>Doyon 在 PLF 的上司，Commander Adama 仍然住在劍橋，並且通過電子郵件和 Doyon 保持着聯絡，他下令讓 Doyon 監視“匿名者”組織，以此獲知其運作方式，並伺機為 PLF 招募新成員。因為癲癇基金會網站入侵事件的那段不愉快回憶，Doyon 拒絕了 Adama。Adama 給 Doyon 解釋説，在“匿名者”組織里不懷好意的黑客只佔極少數，與此相反，這個組織經常會有一些的轟動世界舉動。Doyon 對這點表示懷疑。“4chan 怎麼可能會有轟動世界的大舉動？”他質問道。但出於對 PLF 的忠誠，他還是答應了 Adama 的請求。</p><p>Doyon 經常帶着一台宏基筆記本電腦出入於聖克魯斯的一家名為 Coffee Roasting Company 的咖啡廳。“匿名者”組織的 IRC 聊天室主頻道無需密碼就能進入。Doyon 使用 PLF 的暱稱進行登錄並加入了聊天室。一段時間後，他發現了組織內大量的專用匿名者行動聊天頻道，這些頻道的規模更小，更多專門的組內匿名者間對話相互重複。要想參與行動，你必須知道行動的專用聊天頻道名稱，並且聊天頻道隨時會因為陌生的闖入者而進行變更。這套交流系統並不具備較高的安全係數，但它的確很湊效。“這些專用行動聊天頻道確保了行動機密的高度集中”麥吉爾大學的人類學家 Gabriella Coleman 告訴我。</p><p>有些匿名者提議了一項行動，名為“反擊行動”。如同新聞記者 Parmy Olson 於 2012 年在書中寫道的，“我們是匿名者，” 這項行動是以又一次支持文件共享的網站而創立，如同 Napster 的後繼者海盜灣（Pirate Bay），但隨後其目標卻擴展到了政治領域。2010 年末，在美國國務院的要求下，包括萬事達、Visa、PayPal 在內的幾家公司終止了對維基解密的捐助，維基解密是一家公佈了成百上千份外交文件的自發性組織。在一段在線視頻中，“匿名者”組織揚言要進行報復，發誓會對那些阻礙維基解密發展的公司進行懲罰。Doyon 被這種抗議企業的精神所吸引，決定參加這次行動。</p><img src="http://www.newyorker.com/wp-content/uploads/2014/09/140908_a18473-600.jpg"><p><small>潘多拉的魔盒</small></p><p>在十二月初的“反擊行動”中，“匿名者”組織指導那些新成員，或者説新兵，去看標題為“如何加入那個【嗶~】的Hive”，參與者被要求“首先配置他們【嗶~】的網絡，這【嗶~】的很重要。”同時他們被要求下載“低軌道離子炮”，一款易於使用的開源軟件。Doyon 下載了軟件並在聊天室內等待着下一步指示。當開始的指令發出後，數千名匿名者將同時發動進攻。Doyon 進入了目標網址——www.visa.com——同時，在軟件的右上角有個按鈕，上面寫着“IMMA CHARGIN MAH LAZER.”（“反擊行動”同時也發動了大量的複雜精密的入侵進攻。）幾天後，“反擊行動”攻陷了萬事達、Visa、PayPal 公司的主頁。在法院的控告單上，PayPal 稱這次攻擊給公司造成了 550 萬美元的損失。</p><p>但對 Doyon 來説，這是切實的激進主義體現。在劍橋反對種族隔離的行動中，他不能即可見效；而現在，只需指尖輕輕一點，就可以在攻陷大公司網站的行動中做出自己的貢獻。隔天，赫芬頓郵報上出現了“萬事達淪陷”的醒目標題。一位得意洋洋的匿名者發推特道：“有些事情維基解密是無能為力的。但這些事情卻可以由‘反擊行動’來完成。”</p><h2>4</h2><p>2010 年的秋天，“和平陣營”的抗議活動終止，政府只做出了略微讓步，“流浪者管理法案”仍然有效。Doyon 希望通過藉助“匿名者”組織的方略扭轉局勢。他回憶當時自己的想法，“也許我可以發動‘匿名者’組織來教訓這種看似不堪一擊的市政府網站，它們絕對會【嗶~】地淪陷。最終我們使得市政府永久性廢除‘流浪者管理法案’。”</p><p>Joshua Covelli 是一位 25 歲的匿名者，他的暱稱是“Absolem”，他非常欽佩 Doyon 的果敢。“過去我們的組織完全是各種混亂的一盤散沙，”Covelli 告訴我。在“Commander X”加入之後，“組織似乎開始變得有模有樣了。”Covelli 的工作是俄亥俄州費爾伯恩的一所大學接待員，他從不瞭解任何有關聖克魯斯的政治。但是當 Doyon 提及幫助“和平陣營”抗擊活動的計劃後，Covelli 立即回覆了一封表示贊同的電子郵件：“我期待參加這樣的行動已經很久了。”</p><p>Doyon 使用 PLF 的暱稱邀請 Covelli 在 IRC 聊天室進行了一次秘密談話：</p><blockquote>Absolem：抱歉，有個比較冒犯的問題...請問 PLF 是組織的一部分還是分開的？</blockquote><blockquote>Absolem：我會這麼問，是因為看你們聊天，覺得你們都是非常有組織的。</blockquote><blockquote>PLF：不不不，你的問題一點也不冒犯。很高興遇到你。PLF 是一個來自波士頓的黑客組織，已經成立 22 年了。我在 1981 年就開始了我的黑客生涯，但那時我並沒有使用計算機，而是使用的 PBX（Private Branch Exchange，電話交換機）。</blockquote><blockquote>PLF：我們組織內所有成員的年齡都超過了 40 歲。我們當中有退伍士兵和學者。並且我們的成員“Commander Adama”，正在躲避一大幫警察還有間諜的追捕。</blockquote><blockquote>Absolem：聽起來很棒！我對這次行動很感興趣，不過“匿名者”組織看起來太混亂無序，不知道我是否可以提供一些幫助。我的電腦技術還不錯，但我在入侵技術上還完全是一個新手。我有一些小工具，但不知道怎麼去使用它們。</blockquote><p>莊重的入會儀式後，Doyon 正式接納 Covelli 加入 PLF：</p><blockquote>PLF：把所有可能使你受牽連的敏感文件加密。</blockquote><blockquote>PLF：還有，想要聯繫任何一位 PLF 成員的話，給我發消息就行。從現在起，請叫我... Commander X。</blockquote><p>2012 年，美聯社稱“匿名者”組織為“一幫專家級的黑客”；Quinn Norton 在《連線》雜誌上發文稱“‘匿名者’組織可以入侵任何堅不可摧的網站”，並在文末讚揚他們為“一羣卓越的民間黑客”。事實上，有些匿名者的確是很有天賦的程序員，但絕大部分成員根本不懂任何技術。人類學家 Coleman 告訴我只有大約五分之一的匿名者是真正的黑客——其他匿名者則是“極客與抗議者”。</p><p>2010 年 12 月 16 日，Doyon 以 Commander X 的身份向幾名記者發送了電子郵件。“明天當地時間 12：00 的時候，‘人民解放陣線’組織與‘匿名者’組織將從互聯網中刪除聖克魯斯政府網站”，他在郵件中寫道，“12:30 之後我們將恢復網站的正常運行。”</p><p>聖克魯斯數據中心的工作人員收到了警告，匆忙地準備應對攻擊。他們在服務器上運行起安全掃描軟件，並向當地的互聯網供應商 AT &amp; T 求助，後者建議他們向 FBI 報警。</p><p>第二天，Doyon 走進了一家星巴克並啓動了筆記本電腦。即便是在這樣一個小鎮上，Doyon 也顯得格外醒目：一個疲憊的流浪漢瘋狂地敲擊着鍵盤。隨後，Covelli 和他在一間秘密聊天室碰頭。</p><blockquote>PLF：去社區，登錄——檢查一下右上角的“聊天”菜單欄，上面有今天的具體方案。感謝你對我們的支持。</blockquote><blockquote>Absolem：一切為了 PLF，長官。</blockquote><p>他們都打開了 DDoS 軟件。儘管只有少數人蔘加了這次“和平陣營”的行動，但 Doyon 好似統率千軍萬馬般下令：</p><blockquote>PLF：注意：每一位支持 PLF 或者站在我們這邊的朋友——還有那些對抗邪惡保衞正義的勇士們：‘和平陣營’行動進行中，戰鬥的號角已經響起！目標：www.co.santa-cruz.ca.us。隨意開火。重複指令：開火！</blockquote><blockquote>Absolem：收到，長官。</blockquote><p>數據中心的工作人員緊張地盯着服務器，上面反饋出一連串拒絕服務的請求。儘管他們盡了最大的努力，網站還是崩潰了。25 分鐘後，Doyon 決定遵守承諾。他下令“停止攻擊”，政府網站開始恢復了正常運行。（這次攻擊後，“流浪者管理法案”依舊沒有廢除。）</p><p>Doyon 沒有時間去慶祝勝利，他顯得焦躁不安。“我得走了，”他告訴 Covelli。他飛一般得逃回了山中小屋。Doyon 的感覺是正確的：一位 FBI 的探員早就在 IRC 上盯住了他。這位 FBI 的探員已經獲許搜查 Doyon 的筆記本電腦。</p><p>幾周後，Doyon 的食物吃完了，他不得不下山進行採購。當 Doyon在 Coffee Roasting Company 咖啡廳逗留的時候，兩位聯邦探員走了進來將他拘捕。Doyon 給“和平陣營”的創建者，同時也是一名律師的 Ed Frey 打了一個電話，Ed Frey 來到了警察局。Doyon 告訴了 Frey 他的另一個身份“Commander X”的事。</p><p>隨後 Doyon 被釋放，但 FBI 沒收了他的筆記本電腦，裏面滿是犯罪證據。Frey 一個幾乎不瞭解網絡世界的維權律師，把 Doyon 載回了他的山邊露營。“接着你要怎麼辦？”Frey 問道。</p><img src="http://www.newyorker.com/wp-content/uploads/2014/09/140908_a18447-600.jpg"><p><small>“Zach 很聰明... 並且... 是一個天才... 但.. 你們... 不在一個班。”</small></p><p>Doyon 引用了一句電影台詞。“拼命地跑，”他説。“我會躲起來，儘可能保持我的行動自由，用盡全力和這幫混蛋們作鬥爭。”Frey 給了他兩張 20 美元的鈔票並祝他好運。</p><h2>5</h2><p>Doyon 搭着便車來到了舊金山，並在這裏呆了三個月。他經常混跡於 Haight 大街 Ashbury 區的一家雜亂的咖啡館裏，在計算機前一坐就是幾個小時，只有在抽煙時他才會起身走到室外活動。</p><p>2011 年 1 月，Doyon 聯繫了新聞記者兼匿名者的 Barrett Brown。“我們的下一步計劃是什麼？”Doyon 問道。</p><p>“突尼斯，” Brown 答道。</p><p>“我知道，那是中東地區的一個國家，” Doyon 繼續問，“具體任務是什麼呢？”</p><p>“我們準備打倒那裏的獨裁者，” Brown 再次答道。</p><p>“啊？！那裏有一位獨裁者嗎？” Doyon 有點驚訝。</p><p>幾天後，“突尼斯行動”正式展開。Doyon 作為參與者向突尼斯政府域名下的電子郵箱發送了大量的垃圾郵件，以此阻塞其服務器。“我會提前寫好關於那次行動郵件，接着一次又一次地把它們發送出去，” Doyon 説，“有時候實在沒有時間，我就只簡短的寫上一句‘問候對方母親’的話，然後發送出去。”短短一天時間裏，匿名者們就攻陷了包括突尼斯證券交易所、工業部、總統辦公室、總統辦公室在內的多個網站。他們把總統辦公室網站的首頁替換成了一艘海盜船的圖片，並配以文字“惡有惡報，不是嗎？”</p><p>Doyon 不時會談起他的網上“戰鬥”經歷，似乎他剛從彈坑裏爬出來一樣。“夥計，自從幹了這行我就變黑了，”他向我訴苦道。“你看我的臉，全是抽煙的時候燻的——而且可能已經粘在我的臉上了。我仔細地照過鏡子，毫不誇張地説我簡直就是一頭棕熊。”很多個夜晚，Doyon 都是在 Golden Gate 公園裏露營過夜的。“我就那樣幹了四天，我看了看鏡子裏的‘我’，感覺還可以——但其實我覺得‘我’也許應該去吃點東西、洗個澡了。”</p><p>“匿名者”組織接着又在 YouTube 上聲明瞭將要進行的一系列行動：“利比亞行動”、“巴林行動”、“摩洛哥行動”。作為解放廣場事件的抗議者，Doyon 參與了“埃及行動”。在 Facebook 針對這次行動的宣傳專頁中，有一個為當地示威者準備的“行動套裝”鏈接。“行動套裝”通過文件共享網站 Megaupload 進行分發，其中含有一份加密軟件以及應對瓦斯襲擊的保護措施。在埃及政府關閉了埃及的所有互聯網及子網絡的時候不久後，“匿名者”組織繼續向當地抗議者們提供連接網絡的方法。</p><p>2011 年夏季，Doyon 接替 Adama 成為 PLF 的最高指揮官。Doyon 招募了六個新成員，併力圖發展 PLF 成為“匿名者”組織的中堅力量。Covelli 成為了他的其中一位技術顧問。另一名黑客 Crypt0nymous 負責在 YouTube 上發佈視頻；其餘的人負責研究以及組裝電子設備。與鬆散的“匿名者”組織不同，PLF 內部有一套極其嚴格的管理體系。“Commander X 事必躬親，”Covelli 説。“這是他的行事風格，要麼不做，要麼做好。”一位創立了 AnonInsiders Blog的黑客通過加密聊天告訴我，他認為 Doyon 總是一意孤行——這在“匿名者”組織中是很罕見的現象。“當我們策劃發起一項行動時，他並不在乎其他人是否同意，”這位黑客補充道，“他會一個人列出行動方案，確定攻擊目標，登錄 IRC 聊天室，接着告訴所有人在哪裏‘碰頭’，然後發起 DDoS 攻擊。”</p><p>一些匿名者把 PLF 視為“面子項目”，認為 Doyon 的所作所為完全是個笑柄。“他是因為吹牛出名的，”另一名暱稱為 Tflow 的匿名者 Mustafa Al-Bassam 告訴我。不過，即使是那些極度反感 Doyon 的狂妄自大的人，也不得不承認他在“匿名者”組織發展過程中的重要性。“他所倡導的強硬路線有時很湊效，有時則是礙事，” Gregg Housh 説，並且補充道自己和其他優秀的匿名者都曾遇到過相同的問題。</p><p>“匿名者”組織對外堅持聲稱自己是不分層次的平等組織。在由 Brian Knappenberger 製作的一部紀錄片，《我們是軍團》中，一名成員使用“一羣鳥”來比喻組織，它們輪流領飛帶動整個組織不斷前行。Gabriella Coleman 告訴我，這個比喻不太切合實際，“匿名者”組織內實際上早就出現了一個非正式的領導階層。“領導者非常重要，”她説。“有四五個人可以看做是我們的領頭羊。”她把 Doyon 也算在了其中。但是匿名者們仍然傾向於反抗這種體制結構。在一本即將出版的關於“匿名者”組織的書，《黑客、騙子、告密者、間諜》中，Coleman 這麼寫道，在匿名者中，“成員個體以及那些特立獨行的人依然在一些重大事件上保持着服從的態度，優先考慮集體——特別是那些能引發強烈爭端的事件。”</p><p>匿名者們謔稱那些特立獨行的成員為“自尊心超強的瘋子”和“想讓自己出名的瘋子”。（不過許多匿名者已經不會再隨便給他人取那種具有冒犯性的稱號了。）“但還是有令人驚訝的極少數成員違反規則”打破傳統上的看法，Coleman 説。“這麼做的人，像 Commander X 這樣的，都會在組織里受到排斥。”去年，在一家網絡論壇上，有人寫道，“當他開始把自己比作‘蝙蝠俠’的時候我就不想理他了。”</p><p>Peter Fein，是一位以 n0pants 為暱稱而出名的網絡激進分子，也是眾多反對 Doyon 的浮誇行為的眾多匿名者之一。Fein 瀏覽了 PLF 的網站，其封面上有一個徽章，還有關於組織的宣言——“為了解放眾多人類的靈魂而不斷戰鬥”。Fein 沮喪的發現 Doyon 早就使用真名為這家網站註冊過了，使他這種，以及其他想要找事的匿名者們無機可乘。“如果有人要對我的網站進行 DDoS 攻擊，那完全可以，” Fein 回想起通過私密聊天告訴 Doyon 時的情景，“但如果你要這麼做了的話，我會揍扁你的屁股。”</p><p>2011 年 2 月 5 日，《金融時報》報道了在一家名為 HBGary Federal 的網絡安全公司，首席執行官 HBGary Federal 已經得到了“匿名者”組織骨幹成員名單的消息。Barr 的調查結果表明，三位最高領導人其中之一就是‘ Commander X’，是一位潛伏在加利福尼亞州的黑客而且有能力“策劃一些大型網絡攻擊事件”。Barr 聯繫了 FBI 並提交了自己的調查結果。</p><p>和 Fein 一樣，Barr 也發現了 PLF 網站的註冊法人名為 Christopher Doyon，地址是 Haight 大街。基於 Facebook 和 IRC 聊天室的調查，Barr 斷定‘ Commander X’的真實身份是一名家庭住址在 Haight 大街附近的網絡激進分子 Benjamin Spock de Vries。Barr 通過 Facebook 和 de Vries 取得了聯繫。“請告訴我組織里的其他人，我並不是來抓你們的，” Barr 留言道，“只是想讓‘領導階層’知曉我的意圖。”</p><p>“‘領導階層’？ 2333，笑死我了，” de Vries 回覆道。</p><p>《金融時報》發佈報道的第二天，“匿名者”組織就進行了反擊。HBGary Federal 的網站被進行了惡意篡改。Barr 的私人 Twitter 賬户被盜取，他的上千封電子郵件被泄漏到了網上，同時匿名者們還公佈了他的住址以及其他私人信息——這就是“衝動的懲罰”。不到一個月後，Barr 就從 HBGary Federal 辭職了。</p><h2>6</h2><p>2011 年 4 月，Doyon 離開了舊金山搭便車向西部前行，過着夜晚露宿公園、白天混跡於星巴克的生活。他的背包裏只有一台筆記本電腦、Guy Fawkes 面具，還有在 Pall 超市裏購買的一些東西。</p><img src="http://www.newyorker.com/wp-content/uploads/2014/09/140908_a18563-600.jpg"><p><small>“這是我在 TED 夏令營裏學到的東西。”</small></p><p>他時刻關注着“匿名者”組織的內部消息。那年春季，在 Barr 調查報告中提到的六位匿名者精鋭成員，組建了“LulzSec 安全”組織（Lulz Security），簡稱 LulzSec。這個組織正如其名，這些成員認為“匿名者”組織已經變得太過嚴肅；他們的目標是重新引發起那些“能挑起強烈爭端”的事件。當“匿名者”組織還在繼續支持“阿拉伯之春”的抗議者時，LulzSec 入侵了公共電視網（Public Broadcasting Service，PBS）網站，併發布了一則虛假聲明稱已故説唱歌手 Tupac Shakur 仍然生活在新西蘭。</p><p>匿名者之間會通過 Pastebin.com 網站來共享文本。在這個網站上，LulzSec 發表了一則聲明，稱“很不幸，我們注意到北約和我們的好朋友巴拉克奧薩馬——來自24世紀的奧巴馬 已經提升了關於黑客的籌碼，他們把黑客入侵行為視作一種戰爭的表現。”目標越高遠，挑起的紛爭就越大。6 月 15 日，LulzSec 表示對 CIA 網站受到的襲擊行為負責，他們發表了一條推特，上面寫道“目標擊斃（Tango down，亦即target down）—— cia.gov ——這是起挑釁行為。”</p><p>2011 年 6 月 20 日，LulzSec 的一名十九歲的成員 Ryan Cleary 因為對 CIA 的網站進行了 DDoS 攻擊而被捕。7 月，FBI 探員逮捕了七個月前對 PayPal 進行 DDoS 攻擊的其他十四名黑客。這十四名黑客，每人都面臨着 15 年的牢獄之災以及 50 萬美元的罰款。他們因為圖謀不軌以及故意破壞互聯網而被控違反了計算機欺詐與濫用法案。（Computer Fraud and Abuse Act，該法案允許檢察官擁有寬泛的起訴裁量權，並在去年網絡激進分子 Aaron Swartz 因為被判處 35 年牢獄之災而自殺身亡之後，受到了廣泛的質疑和批評。）</p><p>LulzSec 的成員之一 Jake (Topiary) Davis 因為付不起法律訴訟費，給組織的成員們寫了一封請求幫助的信件。Doyon 進入了 IRC 聊天室把 Davis 需要幫助的消息進行了擴散：</p><blockquote>CommanderX：那麼請大家閲讀信件並給予 Topiary 幫助...</blockquote><blockquote>Toad：你真是為了抓人眼球什麼都做啊！</blockquote><blockquote>Toad：這麼説你得到 Topiary 的消息了？</blockquote><blockquote>CommanderX：Toad 你這個混蛋！</blockquote><blockquote>Katanon：唉...</blockquote><p>Doyon 越來越大膽。在佛羅里達州當局逮捕了支持流浪者的激進分子後，他就攻擊 了奧蘭多商務部商會網站。他使用個人筆記本電腦通過公用無線網絡實施了攻擊，並且沒有花費太多精力來隱藏自己的網絡行蹤。“這種做法很勇敢，但也很愚蠢，”一位自稱 Kalli 的 PLF 的資深成員告訴我。“他看起來並不在乎是否會被抓。他完全是一名自殺式黑客。”</p><p>兩個月後，Doyon 參與了針對舊金山灣區快速交通系統（Bay Area Rapid Transit）的 DDoS 攻擊，以此抗議一名 BART 的警官殺害一名叫做 Charles Hill 的流浪者的事件。隨後 Doyon 現身“CBS 晚間新聞”為這次行動辯護，當然，他處理了自己的聲音，用印花大手帕蓋住了臉。他把 DDoS 攻擊比作為公民的抗議行為。“與佔用 Woolworth 午餐櫃枱的座位相比，這真的沒什麼不同，真的，”他説道。CBS 的主播 Bob Schieffer 笑稱：“就我所見，它並不完全是一項民權運動。”</p><p>2011 年 9 月 22 日，在加利福尼亞州的一家名為 Mountain View 的咖啡店裏，Doyon 被捕，同時面臨着“使用互聯網非法破壞受保護的計算機”的罪名指控。他被拘留了一個星期的時間，接着在簽署協議之後獲得假釋。兩天後，他不顧律師的反對，宣佈將在聖克魯斯郡法院召開會議。他梳起了馬尾辮，戴着一副墨鏡、一頂黑色海盜帽，同時還在脖子上圍了一條五彩手帕。</p><p>Doyon 通過非常誇大的方式揭露了自己的身份。“我就是 Commander X，”他告訴蜂擁的記者。他舉起了拳頭。“作為‘匿名者’組織的一員，作為一名核心成員，我感到非常的驕傲。”他在接受一名記者的採訪時説，“想要成為一名頂尖黑客的話，你只需要準備一台電腦以及一副墨鏡。任何一台電腦都行。”</p><p>Kalli 非常擔心 Doyon 會不小心泄露組織機密或者其他匿名者的信息。“這是所有環節中最薄弱的地方，如果這裏出問題了，那麼組織就完了，”他告訴我。曾在“和平陣營行動”中給予 Doyon 大力幫助的匿名者 Josh Covelli 告訴我，當他在網上看見 Doyon 的新聞發佈會視頻的時候，他感覺瞬間“下巴掉地上了”。“他的所作所為變得越來越不可捉摸，” Covelli 評價道。</p><p>三個月後，Doyon 的指定律師 Jay Leiderman 出席了聖荷西聯邦法庭的辯護。Leiderman 已經好幾個星期沒有得到 Doyon 的消息了。“我需要得知被告無法出席的具體原因，”法官説。Leiderman 無法回答。Doyon 再次缺席了兩星期後的另一場聽證會。檢控方表示：“很明顯，看來被告已經逃跑了。”</p><h2>7</h2><p>“Xport 行動”是“匿名者”組織進行的所有同類行動中的第一個行動。這次行動的目標是協助如今已經揹負兩項罪名的通緝犯 Doyon 潛逃出國。負責調度的人是 Kalli 以及另一位曾在八十年代劍橋的迷幻藥派對上和 Doyon 見過面的匿名者老兵。這位老兵是一位已經退休的軟件主管，在組織內部威望很高。</p><p>Doyon 的目的地是這位軟件主管家，位於加拿大的偏遠鄉村。2011 年 12 月，他搭便車前往舊金山，並輾轉來到了市區組織大本營。他找到了他的指定聯繫人，後者帶領他到達了奧克蘭的一家披薩店。凌晨 2 點，Doyon 通過披薩店的無線網絡，接收了一條加密聊天消息。</p><p>“你現在靠近窗户嗎？”那條消息問道。</p><p>“是的，” Doyon 回覆道。</p><p>“往大街對面看。看見一個綠色的郵箱了嗎？十五分鐘後，你去站到那個郵箱旁邊，把你的背包取下來，然後把你的面具放在上面。”</p><p>一連幾個星期的時間，Doyon 穿梭於海灣地區的安全屋之間，按照加密聊天那頭的指示不斷行動。最後，他搭上了前往西雅圖的長途公交車，軟件主管的一個朋友在那裏接待了他。這個朋友是一名非常富有的退休人員，他花費了幾小時的時間通過谷歌地球來幫助 Doyon 規劃前往加拿大的路線。他們共同前往了一家野外用品供應商店，這位朋友為 Doyon 購置了價值 1500 美元的商品，包括登山鞋以及一個全新的背包。接着他又開車載着 Doyon 北上，兩小時後到達距離國界只有幾百英里的偏僻地區。隨後 Doyon 見到了 Amber Lyon。</p><p>幾個月前，廣播新聞記者 Lyon 曾在 CNN 的關於“匿名者”組織的節目裏採訪過 Doyon。Doyon 很欣賞她的報道，他們一直保持着聯絡。Lyon 要求加入 Doyon 的逃亡行程，為一部可能會發行的紀錄片拍攝素材。軟件主管認為這樣太過冒險，但 Doyon 還是接受了她的請求。“我覺得他是想讓自己出名，” Lyon 告訴我。四天的時間裏，她用影像記錄下了 Doyon 徒步北上，在林間露宿的行程。“那一切看起來不太像是仔細規劃過的，” Lyon 回憶説。“他實在是無家可歸了，所以他才會想要逃到國外去。”</p><img src="http://www.newyorker.com/wp-content/uploads/2014/09/140908_a18506-600.jpg"><p><small>“這裏是我們存放各種情感的倉庫。如果你產生了某種情感，把它帶到這裏然後鎖起來。”</small></p><p>2012 年 2 月 11 日，Pastebin 上出現了一條消息。“PLF 很高興的宣佈‘ Commander X’，也就是 Christopher Mark Doyon，已經離開了美國的司法管轄區，抵達了加拿大一個比較安全的地方，”上面寫着，“PLF 呼籲美國政府，希望政府能夠醒悟過來並停止無謂的騷擾與監視行為——不要僅僅逮捕‘匿名者’組織的成員，對所有的激進組織應該一視同仁。”</p><h2>8</h2><p>Doyon 和軟件主管在加拿大的小木屋裏呆了幾天。在一次同 Barrett Brown 的聊天中，Doyon 難掩內心的喜悦之情。</p><blockquote>BarrettBrown：你現在足夠多安全的藏身之處等等吧？</blockquote><blockquote>CommanderX：是的，我現在很安全，現在加拿大既不缺錢也不缺藏身的地方。</blockquote><blockquote>CommanderX：Amber Lyon 想要你的一張照片。</blockquote><blockquote>CommanderX：去你【嗶~】的怪人，Barrett，相信你會喜歡我的回覆。我一直愛你，永遠愛你。</blockquote><blockquote>CommanderX：:-)</blockquote><blockquote>CommanderX：我告訴她你是一個英雄。</blockquote><blockquote>BarrettBrown：你才是真正的英雄...</blockquote><blockquote>BarrettBrown：很高興你現在安全了</blockquote><blockquote>BarrettBrown：如果你還需要什麼，告訴我一聲就可以了</blockquote><blockquote>CommanderX：我會的，如果這種方式的確很湊效的話，可以讓其他被通緝的人也這樣逃出來....</blockquote><blockquote>BarrettBrown：當然，估計我們不久後也得這樣了</blockquote><p>在 Doyon 出逃十天後，《華爾街日報》上刊登了關於不久後升職為美國國家安全局及網絡指揮部主任的 Keith Alexander 的報道，他在白宮以及其他場合舉行的秘密會晤，表達了對“匿名者”組織的高度關注。Alexander 發出警告，兩年內，該組織必將會是國家電網改造的大患。參謀長聯席會議的主席 General Martin Dempsey 告訴記者，這羣人是國家的敵人。“他們有能力把這些使用惡意軟件造成破壞的技術擴散到其他的邊緣組織去，”隨後又補充道，“我們必須防範這種情況發生。”</p><p>3 月 8 日，國會議員們在國會大廈附近的一個敏感信息隔離設施附近舉行了關於網絡安全的會議。包括 Alexander、Dempsey、美國聯邦調查局局長 Robert Mueller，以及美國國土安全部部長 Janet Napolitano 在內的多名美國安全方面的高級官員出席了這次會議。會議上，通過計算機向與會者模擬了東部沿海地區電力設施可能會遭受到的網絡攻擊時的情境。“匿名者”組織目前應該還不具備發動此種規模攻擊的能力，但安全方面的官員擔心他們會聯合其他更加危險的組織來共同發動攻擊。“在我們着手於不斷增加的網絡風險事故時，政府仍在就具體的處理細節進行不斷協商討論，” Napolitano 告訴我。當談及潛在的網絡安全隱患時，她補充道，“我們通常會把‘匿名者’組織的行動當做 A 級威脅來應對。”</p><p>“匿名者”也許是當今世界上最強大的無政府主義黑客組織。即使如此，它卻從未表現出過任何的會對公共基礎設施造成破壞的跡象或意願。一些網絡安全專家稱，那些關於“匿名者”組織的謠傳太過危言聳聽。“在奧蘭多發佈戰前宣言和實際發動 Stuxnet 蠕蟲病毒攻擊之間是有很大的差距的，” Internet 研究與戰略中心的一位職員 James Andrew Lewis 告訴我，這和 2007 年美國與以色列對伊朗原子能網站發動的黑客襲擊有關。哈佛大學法學院的教授 Yochai Benkler 告訴我，“我們所看見的只是以主要防禦為理由而進行的開銷，否則，將很難自圓其説。”</p><p>Keith Alexander 最近剛從政府部門退休，他拒絕就此事發表評論，因為他並不能代表國家安全局、聯邦調查局、中央情報局以及國土安全部。儘管匿名者們從未真正盯上過政府部門的計算機網絡，但他們對於那些激怒他們的人有着強烈的報復心理。前國土安全部國家網絡安全部門負責人 Andy Purdy 告訴我他們“害怕被報復，”無論機構還是個人，都不同意政府公然反對“匿名者”組織。“每個人都容易成為被攻擊對象，”他説。</p><h2>9</h2><p>2012 年 3 月 6 日，Hector Xavier Monsegur，暱稱為 Sabu 的 LulzSec 骨幹成員，被發現是 FBI 派來的卧底。為了換取減刑，Monsegur 花費了數月的時間卧底，協助蒐集其他 LulzSec 成員的罪證。同一天，五位匿名者領導被捕，同時面臨着包括“計算機某犯罪”在內的多項罪名指控。聯邦調查局的一名官員在接受福克斯新聞記者採訪時説道，“這對那個組織是一個毀滅性的打擊。我們的行動如同砍掉了 LulzSec 組織的頭。”接下來的十個月裏， Barrett Brown 收到了 17 項聯邦罪名的指控，其中的大部分後來被撤銷了。（他將在十月被宣判最終結果。）</p><p>Doyon 感到很煩躁，但他還是繼續扮演着一名黑客——以此吸引關注。他在多倫多上映的紀錄片上以戴着面具的匿名者形象出現。在接受《National Post》的採訪時，他向記者大肆吹噓未經證實的消息，“我們已經入侵了美國政府的所有機密資料庫。現在的問題是我們該何時泄露這些機密數據，而不是我們是否會泄露。”</p><p>2013 年 1 月，在另一名匿名者介入俄亥俄州<a href="https://gist.githubusercontent.com/SteveArcher/cdffc917a507f875b956/raw/c7b49cc11ae1e790d30c87f7b8de95482c18ec74/%E6%96%AF%E6%89%98%E6%9C%AC%E7%BB%B4%E5%B0%94%E8%BD%AE%E5%A5%B8%E6%A1%88%E5%86%8D%E8%B5%B7%E9%A3%8E%E6%B3%A2%20%E9%BB%91%E5%AE%A2%E7%BB%84%E7%BB%87%E4%BB%8B%E5%85%A5">斯托本維爾未成年少女強姦案</a>，發起抗議行動之後，Doyon 重新啓用了他兩年前創辦的網站 LocalLeaks，作為那起強姦事件的信息彙總處理中心。如同許多其他“匿名者”組織的所作所為一樣，LocalLeaks 網站非常具有影響力，但卻也不承擔任何責任。LocalLeaks 網站是第一家公佈 12 分鐘斯托本維爾高中畢業生猥褻視頻的網站，這激起了眾多當事人的憤怒。LocalLeaks 網站上同時披露了幾份未被法庭收錄的關於案件的材料，並且由此不小心透漏出了案件受害人的名字。Doyon向我承認他公開這些未經證實的信息的策略是存在爭議的，但他同時回憶起自己當時的想法，“我們可以選擇銷燬這些斯托本維爾案件的材料...也可以選擇公開所有我們蒐集的信息，基本上，給公眾以提醒，不過，前提是你們得相信我們。”</p><p>2013 年 3 月，一個名為 Rustle League 的組織入侵了 Doyon 的 Twitter 賬户，該組織此前經常挑釁“匿名者”組織。Rustle League 的領導者之一 Shm00p 告訴我，“我們的本意並不是傷害那些傢伙，只不過，哦，那些傢伙説的話你就當是在放屁好了——我會這麼做只是因為我感到很好笑。” Rustle League 組織使用 Doyon 的賬户發佈了含有如 www.jewsdid911.org 鏈接這樣的，種族主義和反猶太主義的信息。</p><p>2013 年 8 月 27 日，Doyon 發佈了一則退出“匿名者”組織的聲明。“我的一生都用在了追求正義和自由上，”他寫道，“也許‘ Commander X’是無敵的，但我在這種高節奏的全球網絡鬥爭中已經感到很累了，感覺自己好像病了。”各界對此反應不一，有同情的（“你是該休息了”），也有嘲諷的（“可憐的瘋狂小老頭。也許他現在有時間洗澡了”）。 Covelli 告訴我，“‘匿名者’的身份對他產生了較大的影響，他已經不能再應付了。”</p><img src="http://www.newyorker.com/wp-content/uploads/2014/09/140908_roberts-1998-08-17-600.jpg"><p><small>1998 年 8 月 17 日 “我們還有‘巴黎’嗎？仔細想想，我等會兒去檢查一下。”</small></p><h2>10</h2><p>2013 年 11 月 5 日舉行了第一次“百萬面具遊行”活動。在全世界四百五十個城市裏，發起了數千人的支持“匿名者”組織的遊行。倫敦的一名抗議者摘下了蓋伊·福克斯面具後，露出了演員羅素·布蘭德的臉。這種的跡象表明，“匿名者”組織已經深入到了流行文化中。</p><p>我參加了華盛頓的集會，Doyon 則呆在了加拿大觀看現場直播。通過移動電話，我和 Doyon 不斷交換着電子郵件。“只能坐在這裏看直播而不能親自去現場真的很令人沮喪——尤其是當這裏麪包含有你努力的結果的時候，”他在郵件裏寫道。“不過至少一切都已有所改變。”</p><p>我們約定了一次面談。Doyon 堅持讓我通過加密聊天把面談的詳細情況提前告訴他。我坐了幾個小時的飛機，租車來到了加拿大的一個偏遠小鎮，並且禁用了我的電話。</p><p>最後，我在一個狹小安靜的住宅區公寓裏見到了 Doyon。他穿了一件綠色的軍人夾克衫以及印有“匿名者”組織 logo 的 T 恤衫：一個臉被問號所替代的黑衣人形象。公寓裏基本上沒有什麼傢俱，充滿了一股煙味。他談論起了美國政治（“我基本沒怎麼在眾多的選舉中投票——它們不過是暗箱操作的遊戲罷了”），好戰的伊斯蘭教（“我相信，尼日利亞政府的人不過是相互勾結，以創建一個名為‘博科聖地’的基地組織的下屬機構罷了”），以及他對“匿名者”組織的小小看法（“那些自稱為怪人的人是真的是爛透了，其實是邪惡的人”）。</p><p>Doyon 剃去了他的鬍鬚，但他卻顯得更加憔悴了。他説那是因為他病了的原因，他幾乎很少出去。很小的寫字枱上有兩台筆記本電腦、一摞關於佛教的書，還有一個堆滿煙灰的煙灰缸。另一面裸露的泛黃牆壁上掛着蓋伊·福克斯面具。他告訴我，“所謂‘Commander X’不過是一個處於極度痛苦中的小老頭罷了。”</p><p>在剛過去的聖誕節裏，匿名者的新網站 AnonInsiders 的創建者拜訪了 Doyon，並給他帶來了餡餅和香煙。Doyon 詢問來訪的朋友是否可以接替自己成為 PLF 的最高指揮官，同時希望能夠遞交出自己手裏的“王國鑰匙”——手裏的所有密碼，以及幾份關於“匿名者”組織的機密文件。這位朋友委婉的拒絕了。“我有自己的生活，”他告訴了我拒絕的理由。</p><h2>11</h2><p>2014 年 8 月 9 日，當地時間下午 5 時 09 分，來自密蘇里州聖路易斯郊區德爾伍德的一位説唱歌手同時也是激進分子的 Kareem (Tef Poe) Jackson，在 Twitter 上談起了鄰近城鎮的一系列令人擔憂的舉措。“基本可以斷定弗格森已經實施了戒嚴，任何人都無法出入，”他在 Twitter 上寫道。“國內外的朋友們請幫助我們！！！”五個小時前，弗格森，一位十八歲的手無寸鐵的非裔美國人 Michael Brown，被一位白人警察射殺。射殺警察聲稱自己這麼做的原因是 Brown 意圖伸手搶奪自己的槍支。而事發當時和 Brown 在一起的朋友 Dorian Johnson 卻説，Brown 唯一做得不對的地方在於他當時拒絕離開街道中間。</p><p>不到兩小時，Jackson 就收到了一位名為 CommanderXanon 的 Twitter 用户的回覆。“你完全可以相信我們，”回覆信息裏寫道。“你是否可以給我們詳細描述一下現場情況，那樣會對我們很有幫助。”近幾周的時間裏，仍然呆在加拿大的 Doyon 復出了。六月，他在還有兩個月滿 50 歲的時候，成功戒煙（“#戒癮成功 #電子香煙功不可沒 #老了，”他在戒煙成功後在 Twitter 上寫道）。七月，在加沙地帶爆發武裝對抗之後，Doyon 發表 Twiter 支持“匿名者”組織的“拯救加沙行動”，並發動了一系列針對以色列網站的 DDoS 攻擊。Doyon 認為弗格森槍擊事件更加令人關注。拋開他本人的個性，他有能力在事件發展到引人注目之前，就迅速注意該事件。</p><p>“正在網上搜索關於那名警察以及當地政府的信息，” Doyon 發 Twitter 道。不到十分鐘，他就為此專門在 IRC 聊天室裏創建了一個頻道。“‘匿名者’組織‘弗格森’行動正式啓動，”他又發了一條 Twitter。但只有兩個人轉推了此消息。</p><p>次日早晨，Doyon 發佈了一條鏈接，鏈接指向的是一個初具雛形的網站，網站首頁有一條致弗格森市民的信息——“你們並不孤單，我們將盡一切努力支持你們”——以及致當地警察的警告：“如果你們對弗格森的抗議者們濫用職權、騷擾，或者傷害了他們，我們絕對會讓你們所有政府部門的網站癱瘓。這不是威脅，這是承諾。”同時 Doyon 呼籲有 130 萬粉絲的“匿名者”組織的 Twitter 賬號 YourAnonNews 給與支持。“請支持‘弗格森’行動”，他發送了消息。一分鐘後，YourAnonNews 回覆表示同意。當天，包含話題 #OpFerguson 的 Twitter 被轉發了超過六千次。</p><p>這個事件迅速成為頭條新聞，同時匿名者們在弗格森周圍進行了大集會。與“阿拉伯之春行動”類似，“匿名者”組織向抗議者們發送了電子關懷包，包括抗暴指導（“把瓦斯彈撿起來回丟給警察”）與可打印的蓋伊·福克斯面具。Jackson 和其他示威者在弗格森進行示威遊行時，警察企圖通過橡皮子彈和催淚瓦斯來驅散他們。“當時的情景真像是布魯斯·威利斯的電影裏的情節，” Jackson 後來告訴我。“不過巴拉克·奧巴馬應該並不會支持‘匿名者’組織傳授給我們的這些知識，”他説道。“知道有人在你的背後支持你，真是感覺欣慰。”</p><p>有個網址是 www.opferguson.com 的網站，後來發現不過是一個騙局——一個用來收集訪問者 ip 地址的陷阱，隨後這些地址會被移交給執法機構。有些人懷疑 Commander X 是政府的線人。在 IRC 聊天室 #OpFerguson 頻道，一個名叫 Sherlock 寫道，“現在頻道里每個人説的已經讓我害怕去點擊任何陌生的鏈接了。除非是一個我非常熟悉的網址，否則我絕對不會去點擊。”</p><p>弗格森的抗議者要求當局公佈射殺 Brown 的警察的名字。幾天後，匿名者們附和了抗議者們的請求。有人在 Twitter 上寫道，“弗格森警察局最好公佈肇事警察的名字，否則‘匿名者’組織將會替他們公佈。”8 月 12 的新聞發佈會上，聖路易斯警察局的局長 Jon Belmar 拒絕了這個請求。“我們不會這樣做，除非他們被某個罪名所指控，”他説道。</p><p>作為報復，一名黑客使用名為 TheAnonMessage 的 Twitter 賬户公佈了一條鏈接，該鏈接指向一段來自警察的無線電設備所記錄的音頻文件，文件記錄時間是 Brown 被槍殺的兩小時左右。TheAnonMessage 同時也把矛頭指向了 Belmar，在 Twitter 上公佈了這位警察局長的家庭住址、電話號碼以及他的家庭照片——一張是他的兒子在長椅上睡覺，另一張則是 Belmar 和他的妻子的合影。“不錯的照片，Jon，” TheAnonMessage 在 Twitter 上寫道。“你的妻子在她這個年齡算是一個美人了。你已經愛她愛得不耐煩了嗎？”一個小時後，TheAnonMessage 又以 Belmar 的女兒為把柄進行了恐嚇。</p><p>Richard Stallman，來自 MIT 的初代黑客，告訴我雖然他在很多地方贊同“匿名者”組織的行為，但他認為這些泄露私人信息的攻擊行為是要受到譴責的。即使是組織內部，TheAnonMessage 的行為也受到了譴責。“為何要泄露無辜的人的信息到網上？”一位匿名者通過 IRC 發問，並且表示威脅 Belmar 的家人實在是“相當愚蠢的行為”。但是 TheAnonMessage 和其他的一些匿名者仍然進行着不斷搜尋，並企圖在將來再次進行泄露信息的攻擊。在互聯網上可以得到所有弗格森警察局警員的名字，匿名者們不斷地搜索着信息，企圖找出具體是哪一個警察找出殺害了 Brown。</p><img src="http://www.newyorker.com/wp-content/uploads/2014/09/140908_steig-1999-04-12-600.jpg"><p><small></small>1999 年 4 月 12 日 “我應該把鏡頭對向誰？”</p><p>8 月 14 日清晨，幾位匿名者基於 Facebook 上的照片還有其他的證據，確定了射殺 Brown 的兇手是一位名叫 Bryan Willman 的 32 歲男子。根據一份 IRC 聊天記錄，一位匿名者貼出了 Willman 的腫脹面孔的照片；另一位匿名者提醒道，“兇手聲稱自己的臉沒有被任何人看到。”另一位暱稱為 Anonymous|11057 的匿名者承認他對 Willman 的懷疑確實是“跳躍性的可能錯誤的邏輯過程推導出來的。”不過他還是寫道，“我只是無法動搖自己的想法。雖然我沒有任何證據，但我非常非常地確信就是他。”</p><p>TheAnonMessage 看起來被這次對話逗樂了，寫道，“#願逝者安息，兇手是 BryanWillman。”另一位匿名者發出了強烈警告。“請務必確認，” Anonymous|2252 寫道。“這不僅僅關乎到一個人的性命，我們可以不負責任地向公眾公佈我們的結果，但卻很可能有無辜的人會因此受到不應受到的對待。”</p><p>爭論超過了一個小時。一些匿名者指出沒有證據表明 Willman 曾經在弗格森警察局任過職。</p><blockquote>Anonymous|3549：@gs 我們依舊沒有證據能夠證明 Bryan 曾在警局呆過</blockquote><blockquote>Intangir：現在的形勢已經夠緊張的了，一旦我們把這個消息公佈出去，可能就會有人因此去殺了他</blockquote><blockquote>Anonymous|11057：唯一的證明方法是犯罪現場目擊者報告。否則我們的結果只是一個謠言</blockquote><blockquote>Anonymous|11057：最快的排除嫌疑的方法是稱他為嫌疑犯...我們都害怕犯下不公正的錯誤，但這種方法恰好可以避免這些...</blockquote><p>大部分匿名者都反對在網上泄露他人信息。但是早晨七點左右匿名者們進行了一次投票。聊天記錄顯示，當時聊天室裏有 80 人左右，只有不到十人蔘與了投票表決。因此他們決定在互聯網上公佈 Willman 的私人信息。</p><blockquote>Anonymous|2252：還在 Twitter 上公佈？</blockquote><blockquote>anondepp：lol</blockquote><blockquote>Anonymous|2252：用 @theanonmessage 公佈？</blockquote><blockquote>TheAnonMessage：當然</blockquote><blockquote>TheAnonMessage：去發吧</blockquote><blockquote>anondepp：搞定了</blockquote><blockquote>Anonymous|2252：我去</blockquote><blockquote>TheAnonMessage：上帝保佑...</blockquote><blockquote>Anonymous|3549：...請拯救我們的靈魂</blockquote><blockquote>anondepp：lol</blockquote><p>早晨 9 時 45 分，聖路易斯警察局對 TheAnonMessage 進行了答覆。“Bryan Willman 從來沒有在 警察局或者聖路易斯警察局任過職，” 他們在 Twitter 上寫道。“請不要再公佈這位無辜市民的信息了。”（隨後 FBI 對弗格森警察的電腦遭黑客入侵的事情展開了調查。）Twitter 管理員迅速封禁了 TheAnonMessage 的賬户，但 Willman 的名字和家庭住址仍然被廣泛傳開。</p><p>實際上，Willman 是弗格森西郊聖安區的警察外勤負責人。當聖路易斯警察局的情報處打電話告訴 Willman，他已經被“確認”為兇手時，他告訴我，“我以為不過是個奇怪的笑話。”幾小時後，他的社交賬號上就收到了成百上千條死亡恐嚇。他在警察的保護下，獨自一人在家裏呆了將近一個星期。“我只希望這一切都儘快過去，”他告訴我他的感受。他認為“匿名者”組織已經不可挽回地損害了他的名譽。“我不知道他們怎麼會以為自己可以被再次信任的，”他説。</p><p>“我們並不完美，” OpFerguson 在 Twitter 上説道。“‘匿名者’組織確實犯錯了，過去的幾天我們製造一些混亂。為此，我們道歉。”儘管 Doyon 並不應該為這次錯誤的信息泄露攻擊負責，但其他的匿名者卻因為他發起了一次無法控制的行動，而歸咎他。YourAnonNews 在 Pastebin 上發表了一則消息，上面寫道，“你們也許注意到了組織不同的 Twitter 賬户發表的話題 #Ferguson 和 #OpFerguson，這兩個話題下的 Twitter 與信息是相互矛盾的。為什麼會在這些關鍵話題上出現分歧，部分原因是因為 CommanderX 是一個‘想讓自己出名的瘋子/想讓公眾認識自己的瘋子’——這種人喜歡，或者至少不迴避媒體的宣傳——並且顯而易見的，組織內大部分成員並不喜歡這樣。”</p><p>在個人 Twitter 上，Doyon 否認了所有關於“弗格森行動”的職責，他寫道，“我討厭這樣。我不希望這樣的情況發生，我也不希望和我認為是朋友的人戰鬥。”沉寂了幾天後，他又再度獲吹響了戰鬥的號角。他最近在 Twitter 上寫道，“你們稱他們是暴民，我們卻稱他們是壓迫下的反抗之聲”以及“解放西藏”。</p><p>Doyon 仍然處於藏匿狀態。甚至連他的律師 Jay Leiderman 也不知道他在哪裏。Leiderman 表示，除了在聖克魯斯受到的指控，Doyon 很有可能因為攻擊了 PayPal 和奧蘭多而面臨新的指控。一旦他被捕，所有的刑期加起來，他的餘生就要在監獄裏度過了。借鑑 Edward Snowden 的先例，他希望申請去俄羅斯避難。我們談話時，他用一支點燃的香煙在他的公寓裏比劃着。“這裏比【嗶~】的牢房強多了吧？我絕對不會出去，”他憤憤道。“我不會再聯繫我的家人了....這是相當高的代價，但我必須這麼做，我會盡我的努力讓所有人活得自由、明白。”</p><p>via: http://www.newyorker.com/magazine/2014/09/08/masked-avengers</p><p>作者：<a href="http://www.newyorker.com/contributors/david-kushner">David Kushner</a></p><p>譯者：<a href="https://github.com/SteveArcher">SteveArcher</a></p><p>校對：<a href="https://github.com/carolinewuyan">Caroline</a></p><p>本文由 <a href="https://github.com/LCTT/TranslateProject">LCTT</a> 原創翻譯，<a href="http://linux.cn/">Linux中國</a>榮譽推出</p>',189)])])}const d=e(p,[["render",r]]);export{D as __pageData,d as default};
